class Positive:
    def __set_name__(self, owner, name):
        self.storage = "_" + name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return self.value

    def __set__(self, obj, value):
        if value <= 0:
            raise ValueError("must be positive")
        self.value = value


class Order:
    quantity = Positive()

class Field:
    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return obj.__dict__["_value"]

    def __set__(self, obj, value):
        obj.__dict__["_value"] = value


class Order:
    price = Field()
    quantity = Field()

class Expensive:
    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        obj.calls += 1
        value = sum(obj.rows)
        obj.__dict__[self.name] = value
        return value

    def __set__(self, obj, value):
        obj.__dict__[self.name] = value


class Report:
    total = Expensive()

    def __init__(self, rows):
        self.rows = rows
        self.calls = 0

class Field:
    def __set_name__(self, owner, name):
        self.storage = "_" + name

    def __get__(self, obj, objtype=None):
        return getattr(obj, self.storage)

    def __set__(self, obj, value):
        setattr(obj, self.storage, value)


class Registry:
    field = Field()


print(Registry.field)

class Upper:
    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return obj.raw.upper()


class Label:
    def __init__(self, raw):
        self.raw = raw


def configure(label):
    """Give this label a computed `shout` attribute."""
    label.shout = Upper()
    return label

class Shape:
    def __init__(self, sides):
        self.sides = sides

    def of(cls, name):
        """Build a shape from a common name."""
        return cls({"triangle": 3, "square": 4}[name])


print(Shape.of("square").sides)

class Cached:
    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, self.name)

    def __set__(self, obj, value):
        setattr(obj, self.name, value)


class Report:
    total = Cached()

class Constant:
    def __init__(self, value):
        self.value = value

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return self.value


class Version:
    number = Constant(1)

tests:
v = Version()
assert v.number == 1

try:
    v.number = 2
except AttributeError:
    pass
else:
    raise AssertionError("a read-only attribute accepted an assignment")
assert v.number == 1
